ALTER TABLE audit_events ADD COLUMN sequence bigint,ADD COLUMN reason text,ADD COLUMN prior_hash text,ADD COLUMN event_hash text;
WITH numbered AS(SELECT workspace_id,id,row_number()OVER(PARTITION BY workspace_id ORDER BY occurred_at,id) AS sequence FROM audit_events)UPDATE audit_events event SET sequence=numbered.sequence,prior_hash=repeat('0',64),event_hash=repeat(md5(event.id::text),2)FROM numbered WHERE event.workspace_id=numbered.workspace_id AND event.id=numbered.id;
ALTER TABLE audit_events ALTER COLUMN sequence SET NOT NULL,ALTER COLUMN prior_hash SET NOT NULL,ALTER COLUMN event_hash SET NOT NULL,ADD UNIQUE(workspace_id,sequence);
CREATE FUNCTION knotline_finalize_audit_chain() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE previous record; BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.workspace_id::text));SELECT sequence,event_hash INTO previous FROM audit_events WHERE workspace_id=NEW.workspace_id ORDER BY sequence DESC LIMIT 1;NEW.sequence=COALESCE(NEW.sequence,COALESCE(previous.sequence,0)+1);NEW.prior_hash=COALESCE(NEW.prior_hash,COALESCE(previous.event_hash,repeat('0',64)));NEW.event_hash=COALESCE(NEW.event_hash,repeat(md5(concat_ws('|',NEW.workspace_id::text,NEW.sequence::text,NEW.actor_id::text,NEW.action,NEW.resource_type,NEW.resource_id::text,NEW.result,NEW.request_id,NEW.metadata::text,NEW.prior_hash)),2));RETURN NEW;END $$;
CREATE TRIGGER audit_events_chain BEFORE INSERT ON audit_events FOR EACH ROW EXECUTE FUNCTION knotline_finalize_audit_chain();
CREATE INDEX audit_events_search_idx ON audit_events(workspace_id,occurred_at DESC,action,resource_type);
CREATE TABLE governance_exports(workspace_id uuid NOT NULL,id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('audit','workspace','user')),subject_user_id uuid,query jsonb NOT NULL DEFAULT '{}'::jsonb,state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','building','ready','failed','expired')),manifest jsonb,integrity_digest text,expires_at timestamptz NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE retention_policies(workspace_id uuid NOT NULL,data_class text NOT NULL,duration_days integer NOT NULL CHECK(duration_days BETWEEN 1 AND 3650),action text NOT NULL CHECK(action IN('delete','anonymize','archive')),version integer NOT NULL DEFAULT 1,effective_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_by uuid NOT NULL,PRIMARY KEY(workspace_id,data_class));
CREATE TABLE legal_holds(workspace_id uuid NOT NULL,id uuid NOT NULL,case_reference text NOT NULL,scope jsonb NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','released')),created_by uuid NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),released_at timestamptz,PRIMARY KEY(workspace_id,id));
CREATE TABLE data_deletion_jobs(workspace_id uuid NOT NULL,id uuid NOT NULL,subject_user_id uuid,scope text NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','blocked_hold','running','attention','complete')),steps jsonb NOT NULL DEFAULT '[]'::jsonb,proof jsonb,requested_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE workspace_data_policies(workspace_id uuid PRIMARY KEY,telemetry text NOT NULL DEFAULT 'minimal',model_providers jsonb NOT NULL DEFAULT '[]'::jsonb,connector_policy jsonb NOT NULL DEFAULT '{}'::jsonb,file_policy jsonb NOT NULL DEFAULT '{}'::jsonb,memory_policy jsonb NOT NULL DEFAULT '{}'::jsonb,public_sharing boolean NOT NULL DEFAULT false,support_access boolean NOT NULL DEFAULT false,allowed_region text NOT NULL DEFAULT 'us',revision integer NOT NULL DEFAULT 1,updated_by uuid NOT NULL);
CREATE TABLE support_access_grants(workspace_id uuid NOT NULL,id uuid NOT NULL,operator_reference text NOT NULL,scope jsonb NOT NULL,reason text NOT NULL,ticket text NOT NULL,access_mode text NOT NULL CHECK(access_mode IN('read','write')),state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','active','revoked','expired')),expires_at timestamptz NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['governance_exports','retention_policies','legal_holds','data_deletion_jobs','workspace_data_policies','support_access_grants'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I_tenant ON %I USING (knotline_tenant_visible(workspace_id)) WITH CHECK (knotline_tenant_visible(workspace_id))',table_name,table_name);END LOOP;END $$;
REVOKE ALL ON audit_events,governance_exports,retention_policies,legal_holds,data_deletion_jobs,workspace_data_policies,support_access_grants FROM PUBLIC;
GRANT SELECT,INSERT ON audit_events TO knotline_runtime;
GRANT SELECT,INSERT,UPDATE,DELETE ON governance_exports,retention_policies,legal_holds,data_deletion_jobs,workspace_data_policies,support_access_grants TO knotline_runtime;
GRANT SELECT ON audit_events,governance_exports,retention_policies,legal_holds,data_deletion_jobs,workspace_data_policies,support_access_grants TO knotline_reporting;
